// Custom Worker entry: the public WebSocket path of the session rooms goes to the
// chase-live worker over the LIVE service binding; everything else is OpenNext.
import { route } from "./lib/server/liveRoute";
/* eslint-disable @typescript-eslint/ban-ts-comment */
// @ts-ignore -- generated by `opennextjs-cloudflare build`
import openNext from "./.open-next/worker.js";

// @ts-ignore -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

interface Env {
  LIVE: { fetch(req: Request): Promise<Response> };
  LIVE_TRANSPORT?: string;
}

const entry = {
  async fetch(req: Request, env: Env, ctx: unknown): Promise<Response> {
    const r = route(req, env);
    if (r === "live") return env.LIVE.fetch(req);
    if (r !== "next") return r;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (openNext as any).fetch(req, env, ctx);
  },
};

export default entry;
